def predict(history, action):
    grid = np.array(history.frames[-1], dtype=np.int8)
    kind = int(action.kind)
    if kind == 6:
        row = int(action.row)
        col = int(action.col)
        # Identify the 2x2 block at the target location
        # Check if the block is currently monochromatic (single value)
        block = grid[row:row+2, col:col+2]
        unique_vals = np.unique(block)
        if len(unique_vals) == 1:
            # If monochromatic, change it to a different color (e.g., 14=green)
            grid[row:row+2, col:col+2] = 14
        else:
            # If mixed, change one of the distinct values to a new color
            if len(unique_vals) > 1:
                target_color = 14
                if target_color not in unique_vals:
                    grid[row:row+2, col:col+2] = target_color
    return {"next_grid": grid, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {}}

