    # Calculate progress based on the number of green cells (14) relative to total cells
    # This satisfies the action-sensitive role by being observable and graded
    grid = np.array(history.frames[-1], dtype=np.int8)
    total_cells = grid.size
    green_cells = np.sum(grid == 14)
    progress = green_cells / total_cells
    return float(np.clip(progress, 0.0, 1.0))

